INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, 1, 321, 0, 125801, 24001, 1, "リリ", 40011, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, 1, 322, 0, 126001, 24001, 1, "クリア", 40011, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (3, 1, 323, 0, 126101, 24001, 1, "プレシア", 40011, "んーと。\nこれ、あげる。\nはい", 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (4, 2, 324, 0, 125801, 24001, 1, "リリ", 40011, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (5, 2, 325, 0, 126001, 24001, 1, "クリア", 40011, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 2);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (6, 2, 326, 0, 126101, 24001, 1, "プレシア", 40011, "お兄。\nきてくれて、うれしい", 2);
